---@class MournChapterEntryCell
---@field Env                           	MournChapterEntryCell                   
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Button                        	UnityEngine.RectTransform               	@ 0    
---@field ImgChapter                    	UnityEngine.RectTransform               	@ 1    
---@field ImgNum                        	UnityEngine.RectTransform               	@ 2    
---@field TxtName                       	UnityEngine.RectTransform               	@ 3    
---@field Finish                        	UnityEngine.RectTransform               	@ 4    
---@field TxtTime                       	UnityEngine.RectTransform               	@ 5    
---@field TransformNode                 	UnityEngine.RectTransform               	@ 6    
---@field ImgLine                       	UnityEngine.RectTransform               	@ 7    
---@field ImgClamp                      	UnityEngine.RectTransform               	@ 8    
local MournChapterEntryCell = Class('MournChapterEntryCell')
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

function MournChapterEntryCell:__init()
	self.data = nil
	self.index = nil
end

function MournChapterEntryCell:__delete()

end

function MournChapterEntryCell:Awake()
	SetButtonAction(self.Button.gameObject, Bind(self,self.OnBtnNodeClick))
end

function MournChapterEntryCell:SetCallBack(callBack)
	self.callBack = callBack
end

function MournChapterEntryCell:RefreshShow(data,index)
	self.data = data
	self.index = index
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting6613, "MournPlotChapterVo", self.data.chapterId)
	if isNotNull(vo) then
		self.vo = vo
		CfUtils.FillImage(self.ImgChapter,vo.picture1)
		CfUtils.FillText(self.TxtName,vo.name)
		CfUtils.FillImage(self.ImgNum,vo.icon)
		local isPass = ActivityMournUtils.IsUnLockChapter(self.data.chapterId)
		CfUtils.SetActive(self.Finish.gameObject,isPass)
		if isPass then
			CfUtils.SetActive(self.Lock.gameObject,false)
		else
			---通关上一关 并且时间到了
			local isUnLock = self:IsLock()
			CfUtils.SetActive(self.Lock.gameObject,not isUnLock)
			if not isUnLock then
				self:SetLockParams()
			end
		end
	end
	
	if self.index % 2 ==0 then
		self.TransformNode.anchoredPosition = Vector3(0, 73, 0)
		self.ImgLine.localRotation = Quaternion.Euler(0, 0, 19.7)
		self.ImgClamp.localScale = Vector3(1, 1, 1)
	else
		self.TransformNode.anchoredPosition = Vector3(0, 0, 0)
		self.ImgLine.localRotation = Quaternion.Euler(0, 0, 0)
		self.ImgClamp.localScale = Vector3(-1, 1 , 1)
	end
end

function MournChapterEntryCell:IsLock()
	return ActivityMournUtils.IsUnLockChapter(checkNumber(self.vo.unlockChapter)) and (checkNumber(self.data.unlockCountdown) - os.time()) <= 0
end

function MournChapterEntryCell:SetLockParams()
	local time = checkNumber(self.data.unlockCountdown) - os.time()
	CfUtils.SetActive(self.TxtTime.gameObject,time > 0)
	if time > 0 then
		CfUtils.FillText(self.TxtTime,localize("_num_开启",{_num_ = CfUtils.GetTimeHMS11(time)}))
	else
		CfUtils.FillText(self.TxtTime,localize("请先通关前置关卡"))
	end
end

function MournChapterEntryCell:OnBtnNodeClick()
	local isPass = ActivityMournUtils.IsUnLockChapter(self.data.chapterId)
	if isPass then
		CfUtils.DialogOpen(Constants.UITypeIds.MournPlotDialog, { chapterId = self.data.chapterId } , { { id = Constants.UITypeIds.MournChapterEntryDialog } })
	else
		local isLock = self:IsLock()
		if not isLock then
			self:ShowLockTips()
			return
		end
		CfUtils.DialogOpen(Constants.UITypeIds.MournPlotDialog, { chapterId = self.data.chapterId } , { { id = Constants.UITypeIds.MournChapterEntryDialog } })
	end
end

function MournChapterEntryCell:ShowLockTips()
	local curTime = os.time()
	local time = checkNumber(self.data.unlockCountdown) - curTime
	if time > 0 then
		GameUtils.Toast(localize("_num_开启",{_num_ = CfUtils.GetTimeHMS11(time)}))
	else
		GameUtils.Toast(localize("请先通关前置关卡"))
	end
end

function MournChapterEntryCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return MournChapterEntryCell